using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CellariusCharacterAchievement", menuName = "Data/Characters/CellariusCharacterAchievement")]
public class CellariusCharacterAchievement : CharacterAchievement
{
	[SerializeField]
	private AchievementData boundlessasOceanAchievementData;

	public override void OnEnemyPurified(int purifyAmount, CorruptedAnimalCorruptionStats corruptedAnimalCorruptionStats, GameObject source)
	{
		if (purifyAmount == EffectsValues.NO_VALUE)
		{
			boundlessasOceanAchievementData.Unlock();
		}
	}
}
